// --- CONFIGURAZIONE ---
u_min := 0;
u_max := 6.28318; // 2*PI
v_min := 0;
v_max := 6.28318;
steps := 350;

// --- CODICE SHADER ---
// NB: non dichiarare variabili chiamate PI, pi, tau: il traduttore
// le sostituisce col valore numerico in tutto lo script.

// Parametri Geometrici
float a = 3.0;  // Ampiezza del quadrifoglio
float r = 0.25; // Raggio del tubo

// Curva: quadrifoglio (rosa polare rho = a*cos(2*theta)) nel piano
// z=0. Passa QUATTRO volte per l'origine (u = 0.7854 + k*1.5708):
// li' i quattro rami si incrociano e il tubo si autointerseca.
// NB: i rami opposti (k e k+2) arrivano all'origine TANGENTI alla
// stessa retta (y=x oppure y=-x), quindi la fusione dei bracci al
// centro e' piu' estesa che nella lemniscata (con questi parametri
// arriva a raggio ~1.24): e' geometria vera, non un artefatto.
float c2u = cos(2.0 * u);
float s2u = sin(2.0 * u);
vec3 Curve = vec3(a * c2u * cos(u), a * c2u * sin(u), 0.0);

// --- DERIVATA PRIMA (Velocita' Analitica) ---
vec3 dC = vec3(
    -2.0 * a * s2u * cos(u) - a * c2u * sin(u),
    -2.0 * a * s2u * sin(u) + a * c2u * cos(u),
    0.0
);

vec3 Tangent = normalize(dC);

// --- CALCOLO FRAME STABILE ---
// La curva sta nel piano z=0: la tangente non risulta mai parallela
// a Z, quindi il frame non degenera mai.
vec3 Up = vec3(0.0, 0.0, 1.0);
vec3 Binorm = normalize(cross(Tangent, Up));
vec3 Norm = normalize(cross(Binorm, Tangent));

// --- COSTRUZIONE TUBO ---
vec3 pos = Curve + r * (cos(v) * Norm + sin(v) * Binorm);

// Ritorno del punto in 4D (X, Y, Z, P)
return vec4(pos * 0.35, 0.0);

//CUTOUT_BEGIN
// Taglio delle pareti interne nella zona dell'incrocio (origine).
// Schema ereditato dal Tubo Autointersecante (lemniscata): distanza
// PRECISA con scansione grossolana + 5 passi di Newton — i campioni
// grezzi da soli stimano il minimo con errore ~1e-2 e producono
// toppe di z-fight e bordi frastagliati lungo la cucitura.
// Differenza: i nodi qui sono QUATTRO (u_k = 0.7854 + k*1.5708,
// tutti nell'origine) e per un frammento vicino al nodo k si
// controllano i rami degli altri TRE nodi. Il proprio ramo non puo'
// toccarsi (verificato numericamente: resta a distanza >= 0.55 con
// r = 0.25), quindi si salta.
float a2 = 3.0;
float r2 = 0.25;
float PI_2 = 3.14159265359;

// nodo piu' vicino al frammento (in parametro, con wrap su 2*PI)
float uw = u - PI_2 * 2.0 * floor(u / (PI_2 * 2.0));
float kNear = floor((uw - PI_2 * 0.25) / (PI_2 * 0.5) + 0.5);
float uNode = PI_2 * 0.25 + kNear * PI_2 * 0.5;

float activateWindow = 0.5;
bool didCut = false;

if (abs(uw - uNode) < activateWindow) {
    float c2f = cos(2.0 * u);
    float s2f = sin(2.0 * u);
    vec3 Curve2 = vec3(a2 * c2f * cos(u), a2 * c2f * sin(u), 0.0);
    vec3 dC2 = vec3(
        -2.0 * a2 * s2f * cos(u) - a2 * c2f * sin(u),
        -2.0 * a2 * s2f * sin(u) + a2 * c2f * cos(u),
        0.0
    );
    vec3 Tangent2 = normalize(dC2);
    vec3 Up2 = vec3(0.0, 0.0, 1.0);
    vec3 Binorm2 = normalize(cross(Tangent2, Up2));
    vec3 Norm2 = normalize(cross(Binorm2, Tangent2));
    vec3 pos2 = Curve2 + r2 * (cos(v) * Norm2 + sin(v) * Binorm2);

    float bestDist = 1000.0;

    for (float j = 0.0; j < 4.0; j = j + 1.0) {
        float node = PI_2 * 0.25 + j * PI_2 * 0.5;
        // salta il nodo del frammento (equivalenza mod 2*PI)
        float dn = abs(node - uNode);
        dn = min(dn, PI_2 * 2.0 - dn);
        if (dn < 0.1) { continue; }

        // 1. scansione grossolana attorno al nodo
        float bestU = node;
        float bestD = 1000.0;
        for (float k = 0.0; k < 16.0; k = k + 1.0) {
            float u2 = node - 0.4 + 0.8 * (k / 15.0);
            float cc = cos(2.0 * u2);
            vec3 c2 = vec3(a2 * cc * cos(u2), a2 * cc * sin(u2), 0.0);
            float d = length(pos2 - c2);
            if (d < bestD) { bestD = d; bestU = u2; }
        }

        // 2. Newton su g(u2) = dot(pos2 - C(u2), C'(u2)) = 0
        float uN = bestU;
        for (float it = 0.0; it < 5.0; it = it + 1.0) {
            float cN2 = cos(2.0 * uN);
            float sN2 = sin(2.0 * uN);
            float cN1 = cos(uN);
            float sN1 = sin(uN);
            vec3 cN = vec3(a2 * cN2 * cN1, a2 * cN2 * sN1, 0.0);
            vec3 t1 = vec3(-2.0 * a2 * sN2 * cN1 - a2 * cN2 * sN1,
                           -2.0 * a2 * sN2 * sN1 + a2 * cN2 * cN1, 0.0);
            vec3 t2 = vec3(a2 * (-5.0 * cN2 * cN1 + 4.0 * sN2 * sN1),
                           a2 * (-5.0 * cN2 * sN1 - 4.0 * sN2 * cN1), 0.0);
            vec3 w = pos2 - cN;
            float g = dot(w, t1);
            float gp = dot(w, t2) - dot(t1, t1);
            if (abs(gp) > 0.000001) { uN = uN - g / gp; }
            uN = clamp(uN, node - 0.45, node + 0.45);
        }
        float cB2 = cos(2.0 * uN);
        vec3 cB = vec3(a2 * cB2 * cos(uN), a2 * cB2 * sin(uN), 0.0);
        bestDist = min(bestDist, min(bestD, length(pos2 - cB)));
    }

    didCut = (bestDist < r2);
}

return didCut;
//CUTOUT_END

